def choose_move(observation):
    wx, wy = observation['grid_width'], observation['grid_height']
    x, y = observation['self_position']
    ox, oy = observation['opponent_position']
    resources = observation.get('resources', [])
    obstacles = observation.get('obstacles', [])
    score_self = observation.get('scores', [0])[0]
    score_opp = observation.get('scores', [0, 0])[1]
    path_self = observation.get('self_path', [])
    path_opp = observation.get('opponent_path', [])
    def is_free(cxi, cyi):
        if 0 <= cxi < wx and 0 <= cyi < wy:
            return (cxi, cyi) not in obstacles and (cxi, cyi) != (ox, oy)
        return False
    # Compute closest resource
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    close_res = None
    min_d = float('inf')
    for r in resources:
        d = dist((x,y), r)
        if d < min_d:
            min_d = d
            close_res = r
    # Decide move towards resource
    dx = dy = 0
    if close_res:
        dx = close_res[0] - x
        dy = close_res[1] - y
        if abs(dx) > abs(dy):
            step_x = 1 if dx > 0 else -1
            if is_free(x + step_x, y):
                return [step_x, 0]
            elif is_free(x, y + (1 if dy > 0 else -1)):
                return [0, 1 if dy > 0 else -1]
        else:
            step_y = 1 if dy > 0 else -1
            if is_free(x, y + step_y):
                return [0, step_y]
            elif is_free(x + (1 if dx > 0 else -1), y):
                return [1 if dx > 0 else -1, 0]
    # Else, move to center if safe
    def safe_moves():
        moves = {'left':(-1,0),'right':(1,0),'up':(0,-1),'down':(0,1)}
        for move, (dx,mv) in moves.items():
            nx, ny = x + dx, y + mv
            if is_free(nx, ny):
                return dx, mv
        return 0,0
    return safe_moves()
